# Names the game asks for that are heard as another's recordings: a blade sounds the same in skin, fat, flesh and
# whatever is inside.
ALSO = {'skin': ['fat', 'flesh', 'organ', 'snip']}


def run(*args):
    return subprocess.run(args, check=True, capture_output=True, text=True)


def main(downloads, out):
    os.makedirs(out, exist_ok=True)
    for old in os.listdir(out):
        if old.endswith(('.flac', '.ogg')):
            os.remove(os.path.join(out, old))
    manifest, credits = {}, []
    for file, (generation, asked) in TAKES.items():
        name = re.sub(r'-\d+$', '', file)
        source = os.path.join(downloads, file + '.mp3')
        # Mono, rumble off; a one-shot loses its silent tail (reversed, its silent head).
        shaped = 'aformat=channel_layouts=mono,highpass=f=35'
        if name not in LOOPS:
            shaped += ',areverse,silenceremove=start_periods=1:start_threshold=-60dB,areverse'
        said = run('ffmpeg', '-hide_banner', '-nostats', '-i', source, '-af', shaped + ',ebur128=peak=true', '-f', 'null', '-').stderr
        summary = said[said.rindex('Summary:'):]
        lufs, peak = (float(re.search(p, summary).group(1)) for p in (r'I:\s+(-?[\d.]+) LUFS', r'Peak:\s+(-?[\d.]+) dBFS'))
        gain = min(LOUD - lufs, PEAK - peak)
        run('ffmpeg', '-y', '-v', 'error', '-i', source, '-af', f'{shaped},volume={gain:.2f}dB', '-ar', '48000',
            '-c:a', 'libvorbis', '-q:a', '6', os.path.join(out, file + '.ogg'))
        for each in [name] + ALSO.get(name, []):
            manifest.setdefault(each, []).append(file + '.ogg')
        credits.append(f'- `{file}.ogg`: "{asked}". ElevenLabs flow {FLOW}, generation {generation.split("/")[1]}.')
        print(f'{file:16} {lufs:6.1f} LUFS, peak {peak:5.1f}, {gain:+5.1f} dB')
    with open(os.path.join(out, 'manifest.json'), 'w') as f:
        json.dump(manifest, f, indent=1)
    with open(os.path.join(out, 'CREDITS.md'), 'w') as f:
        f.write('# The sound effects\n\nGenerated with ElevenLabs Sound Effects v2 (eleven_text_to_sound_v2) from the prompt beside each,\n'
                'one channel, set to a level (tools/sfx.py). Voices are in assets/cries (Fish Audio).\n\n' + '\n'.join(credits) + '\n')


if __name__ == '__main__':
    main(*sys.argv[1:3])
